sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.profissionalId = '';
    c.novo = { aberto: false, clienteId: '', servicoId: '', profissionalId: '', dataHora: '', erro: null };

    c.carregar = function() {
        c.data.action = 'listar';
        c.data.profissionalId = c.profissionalId;
        c.server.update();
    };

    c.agendar = function() {
        c.novo.erro = null;
        c.data.action = 'agendar';
        c.data.clienteId = c.novo.clienteId;
        c.data.servicoId = c.novo.servicoId;
        c.data.profissionalId = c.novo.profissionalId;
        c.data.dataHora = c.novo.dataHora;
        c.server.update().then(function(r) {
            if (r.data.erro) {
                c.novo.erro = r.data.erro;
            } else {
                c.novo.aberto = false;
                c.carregar();
            }
        });
    };

    c.carregar();
};

sp_widget.script:
(function() {
    data.profissionais = [];
    var profGr = new GlideRecord('x_espaco_profissional');
    profGr.addQuery('ativo', true);
    profGr.query();
    while (profGr.next()) {
        data.profissionais.push({ sys_id: profGr.getUniqueValue(), nome: profGr.getValue('nome') });
    }

    if (input && input.action === 'agendar') {
        try {
            new AgendarSessaoUseCase().execute({
                clienteId: input.clienteId,
                servicoId: input.servicoId,
                profissionalId: input.profissionalId,
                dataHora: input.dataHora
            });
        } catch (e) {
            data.erro = e.message || 'Não foi possível criar o agendamento.';
        }
        return;
    }

    data.agendamentos = [];
    var gr = new GlideRecord('x_espaco_agendamento');
    if (input && input.profissionalId) {
        gr.addQuery('profissional', input.profissionalId);
    }
    gr.orderByDesc('data_hora');
    gr.setLimit(50);
    gr.query();
    while (gr.next()) {
        data.agendamentos.push({
            sys_id: gr.getUniqueValue(),
            data_hora: gr.getValue('data_hora'),
            status: gr.getValue('status'),
            cliente_nome: gr.cliente.nome.toString(),
            servico_nome: gr.servico.nome.toString(),
            profissional_nome: gr.profissional.nome.toString()
        });
    }
})();
